from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
import pytest

counter = 0

def dep_a():
    global counter
    counter += 1
    return "a"

def dep_b(a=Depends(dep_a)):
    return a

def dep_c(a=Depends(dep_a)):
    return a

app = FastAPI()

@app.get("/")
async def root(b=Depends(dep_b), c=Depends(dep_c)):
    return {"b": b, "c": c}

client = TestClient(app)

def test_cache_no_scopes():
    global counter
    counter = 0
    response = client.get("/")
    assert response.status_code == 200
    assert response.json() == {"b": "a", "c": "a"}
    assert counter == 1, f"dep_a should be called once, but was called {counter} times"

if __name__ == "__main__":
    try:
        test_cache_no_scopes()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
", "filepath": "_check.py"}

